    def is_seq(x):
        return isinstance(x, (list, tuple))

    def pos(obj, default=(0, 0)):
        if is_seq(obj) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def move_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def move_away(a, b):
        return [sgn(a[0] - b[0]), sgn(a[1] - b[1])]

    def get(obs, key, default=None):
        return obs.get(key, default) if isinstance(obs, dict) else default

    obs = observation if isinstance(observation, dict) else {}
    env = get(obs, "environment_name", "") or get(obs, "task_name", "") or ""

    sx, sy = pos(get(obs, "self_position", (0, 0)), (0, 0))
    ox, oy = pos(get(obs, "opponent_position", (sx, sy)), (sx, sy))
    w = get(obs, "grid_width", 0) or get(obs, "width", 0) or 0
    h = get(obs, "grid_height", 0) or get(obs, "height", 0) or 0

    def best_cell(cells, ref):
        best = None
        best_d = None
        for c in cells or []:
            p = pos(c, None)
            if p is None:
                continue
            d = manhattan(p, ref)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    if env == "pursuit_evasion":
        role = get(obs, "self_role", "pursuer")
        if role == "pursuer":
            return move_toward((sx, sy), (ox, oy))
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = max(corners, key=lambda c: manhattan(c, (ox, oy)))
        return move_toward((sx, sy), target)

