    resource_keys = ("resources", "resource_positions", "resource_cells", "targets", "food", "apples", "coins")
    resources = []
    for key in resource_keys:
        items = get(obs, key, [])
        if items:
            resources = items
            break

    target = best_cell(resources, (sx, sy))
    if target is not None:
        # If opponent is closer to the same resource, bias slightly away to avoid simple denial traps.
        if manhattan((ox, oy), target) <= manhattan((sx, sy), target):
            away = move_away((sx, sy), (ox, oy))
            if away != [0, 0]:
                return away
        return move_toward((sx, sy), target)

    allies = get(obs, "allied_positions", []) or get(obs, "teammate_positions", [])
